[CmdletBinding()]
param([Parameter(Mandatory=$true)][ValidateSet('Initialize','Update','Discover','Validate')][string]$Action,[string]$TeamId,[string]$DisplayName,[string]$Mission='',[string[]]$MemberPersonIds=@(),[string[]]$MemberRoles=@(),[string]$BranchStrategy='team branch + reviewed merge',[string]$MergePolicy='no direct main push; require evidence before merge',[int]$ExpectedRevision=0,[switch]$TransferOwnership,[string]$ProjectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..')).Path)
$ErrorActionPreference='Stop'; $utf8=[Text.UTF8Encoding]::new($false,$true); $root=(Resolve-Path -LiteralPath $ProjectRoot).Path; $public=Join-Path $root 'ES\AISpace\Public\Teams'; $people=Join-Path $root 'ES\AISpace\Public\People'
function ReadJ($p){$utf8.GetString([IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $p).Path))|ConvertFrom-Json}; function WriteJ($p,$v){[IO.Directory]::CreateDirectory((Split-Path $p))|Out-Null;[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 12),$utf8)}; function HashJ($v){$c=$v|ConvertTo-Json -Depth 12|ConvertFrom-Json;$c.contentHash=$null;$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash([Text.Encoding]::UTF8.GetBytes(($c|ConvertTo-Json -Depth 12 -Compress)))).Replace('-','')).ToLowerInvariant()}finally{$s.Dispose()}}; function Owner(){ $s=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$h=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()} }; function Id($x){if($x -notmatch '^[a-z][a-z0-9-]{1,47}$'){throw "InvalidTeamId:$x"}}
function Check($r,$p){Id $r.teamId;if([string]$r.contentHash -ne (HashJ $r)){throw "ContentHashMismatch:$p"};$seen=@{};foreach($m in @($r.members)){if($seen.ContainsKey($m.personId)){throw "DuplicateMember:$($m.personId)"};$seen[$m.personId]=$true;if($m.role -notin @('Owner','Maintainer','Contributor','Reader')){throw "InvalidRole:$($m.role)"};if(-not(Test-Path (Join-Path (Join-Path $people $m.personId) 'registration.json'))){throw "MemberNotFound:$($m.personId)"}}}
if($Action -eq 'Initialize'){$null=Id $TeamId;if([string]::IsNullOrWhiteSpace($DisplayName)){throw 'DisplayNameRequired'};$p=Join-Path (Join-Path $public $TeamId) 'team.json';if(Test-Path $p){throw "AlreadyExists:$p"};if($MemberPersonIds.Count -lt 1 -or $MemberRoles.Count -ne $MemberPersonIds.Count){throw 'MembersAndRolesRequired'};$ms=@();for($i=0;$i -lt $MemberPersonIds.Count;$i++){$ms+=[ordered]@{personId=$MemberPersonIds[$i];role=$MemberRoles[$i]}};$r=[ordered]@{schemaVersion=1;teamId=$TeamId;displayName=$DisplayName;mission=$Mission;members=$ms;collaboration=[ordered]@{branchStrategy=$BranchStrategy;mergePolicy=$MergePolicy};ownerSubjectHash=(Owner);status='Active';revision=1;contentHash='';updatedUtc=[DateTimeOffset]::UtcNow.ToString('O')};$r.contentHash=HashJ $r;WriteJ $p $r;Write-Output $p}
if($Action -eq 'Update'){$p=Join-Path (Join-Path $public $TeamId) 'team.json';if($ExpectedRevision -lt 1){throw 'ExpectedRevisionRequired'};$mx=[Threading.Mutex]::new($false,'ESTeamSpace-'+($root-replace '[^a-zA-Z0-9]','_')+'-'+$TeamId);if(-not $mx.WaitOne(30000)){$mx.Dispose();throw 'UpdateLockTimeout'};try{$r=ReadJ $p;Check $r $p;if([string]$r.ownerSubjectHash -ne (Owner) -and -not $TransferOwnership){throw "OwnerSubjectMismatch:$p (use -TransferOwnership to take over)"};if([int]$r.revision -ne $ExpectedRevision){throw "RevisionConflict:$($r.revision)"};if($PSBoundParameters.ContainsKey('DisplayName')){$r.displayName=$DisplayName};if($PSBoundParameters.ContainsKey('Mission')){$r.mission=$Mission};if($PSBoundParameters.ContainsKey('BranchStrategy')){$r.collaboration.branchStrategy=$BranchStrategy};if($PSBoundParameters.ContainsKey('MergePolicy')){$r.collaboration.mergePolicy=$MergePolicy};if($TransferOwnership){$r.ownerSubjectHash=Owner};$r.revision=[int]$r.revision+1;$r.updatedUtc=[DateTimeOffset]::UtcNow.ToString('O');$r.contentHash='';$r.contentHash=HashJ $r;WriteJ $p $r;Check $r $p|Out-Null;Write-Output ($r|ConvertTo-Json -Depth 8)}finally{$mx.ReleaseMutex();$mx.Dispose()}}
if($Action -eq 'Discover' -or $Action -eq 'Validate'){$xs=@(Get-ChildItem -LiteralPath $public -Recurse -Filter team.json -File -ErrorAction SilentlyContinue|%{$r=ReadJ $_.FullName;Check $r $_.FullName;[pscustomobject]@{path=$_.FullName;teamId=$r.teamId;displayName=$r.displayName;members=@($r.members).Count;revision=$r.revision;valid=$true}});[pscustomobject]@{action=$Action;status='passed';count=$xs.Count;teams=$xs;runtimeStatus='runtime-not-run'}|ConvertTo-Json -Depth 10}
